int vfs_rename(struct inode *old_dir, struct dentry *old_dentry, struct inode *new_dir, struct dentry *new_dentry, struct inode **delegated_inode, unsigned int flags)
{
    int error;

    if (old_dir == NULL || old_dentry == NULL || new_dir == NULL || new_dentry == NULL)
        return -EINVAL;

    if (old_dentry->d_inode == NULL)
        return -ENOENT;

    if (old_dir == new_dir && old_dentry == new_dentry)
        return 0;

    error = inode_permission(old_dir, MAY_WRITE | MAY_EXEC);
    if (error)
        return error;

    error = inode_permission(new_dir, MAY_WRITE | MAY_EXEC);
    if (error)
        return error;

    if (S_ISDIR(old_dentry->d_inode->i_mode)) {
        error = inode_permission(old_dentry->d_inode, MAY_EXEC);
        if (error)
            return error;
    }

    if (S_ISDIR(new_dentry->d_inode->i_mode)) {
        error = inode_permission(new_dentry->d_inode, MAY_EXEC);
        if (error)
            return error;
    }

    if (flags & RENAME_EXCHANGE) {
        struct inode *tmp_inode = old_dentry->d_inode;
        old_dentry->d_inode = new_dentry->d_inode;
        new_dentry->d_inode = tmp_inode;
    }

    error = old_dir->i_op->rename(old_dir, old_dentry, new_dir, new_dentry, flags);
    if (error)
        return error;

    if (delegated_inode && *delegated_inode) {
        iput(*delegated_inode);
        *delegated_inode = NULL;
    }

    d_move(old_dentry, new_dentry);
    fsnotify_move(old_dir, new_dir, old_dentry, new_dentry);

    return 0;
}
